using System;
using System.IO;
using MassiveArmy.Planetary;
static class CompassChecks {
 static int count;static void Check(bool condition,string text){if(!condition)throw new Exception(text);count++;Console.WriteLine("PASS "+text);}
 static bool Near(double a,double b,double tolerance=1e-9)=>Math.Abs(a-b)<tolerance;
 static void Main(){
  var front=NavigationCompassMath.Project(0,1,0,0);Check(front.valid&&Near(front.bearing,0)&&Near(front.pitchError,0)&&Near(front.scale,1),"A directly faced target is centered and full size");
  Check(Near(NavigationCompassMath.Project(1,0,0,0).bearing,90),"Right bearing is positive 90 degrees");Check(Near(NavigationCompassMath.Project(-1,0,0,0).bearing,-90),"Left bearing is negative 90 degrees");var rear=NavigationCompassMath.Project(0,-1,0,0);Check(Near(rear.bearing,180)&&Near(NavigationCompassMath.BarPosition(rear.bearing),1),"A target behind the observer stays at the rear seam, never center");
  double angle=Math.PI/3;var high=NavigationCompassMath.Project(0,Math.Cos(angle),Math.Sin(angle),0);Check(Near(high.bearing,0)&&Near(high.pitchError,60)&&Near(high.scale,.52),"Matching yaw with a 60 degree pitch error keeps the icon centered but smaller");var faced=NavigationCompassMath.Project(0,Math.Cos(angle),Math.Sin(angle),60);Check(Near(faced.bearing,0)&&Near(faced.pitchError,0)&&Near(faced.scale,1),"Pitching up to the target restores full icon size");
  Check(NavigationCompassMath.Project(0,1,-1,0).pitchError<0,"A low target gives a pitch-down cue");Check(Near(NavigationCompassMath.Project(1,0,0,0).scale,1),"Horizontal bearing does not masquerade as pitch misalignment");
  var zenith=NavigationCompassMath.Project(0,0,1,0);var nadir=NavigationCompassMath.Project(0,0,-1,0);Check(Near(zenith.bearing,0)&&Near(zenith.pitchError,90)&&Near(zenith.scale,.36),"Straight-up targets have stable centered azimuth and a small pitch cue");Check(Near(nadir.bearing,0)&&Near(nadir.pitchError,-90)&&Near(nadir.scale,.36),"Straight-down targets remain finite and centered");Check(Near(NavigationCompassMath.Project(0,0,1,90).scale,1),"A correctly faced vertical target is full size");
  Check(!NavigationCompassMath.Project(0,0,0,0).valid,"Coincident targets have no invented bearing");Check(!NavigationCompassMath.Project(double.NaN,1,0,0).valid&&!NavigationCompassMath.Project(1,double.PositiveInfinity,0,0).valid&&!NavigationCompassMath.Project(1,1,0,double.NaN).valid,"Nonfinite direction and pitch inputs are rejected");
  var far=NavigationCompassMath.Project(1e200,2e200,3e200,15);var near=NavigationCompassMath.Project(1,2,3,15);Check(far.valid&&Near(far.bearing,near.bearing)&&Near(far.pitchError,near.pitchError)&&Near(far.scale,near.scale),"Galactic-scale directions normalize without overflow or float precision loss");
  Check(Near(NavigationCompassMath.Wrap(359),-1)&&Near(NavigationCompassMath.Wrap(-359),1)&&Near(NavigationCompassMath.Wrap(721),1),"Compass angles wrap across north and multiple turns");Check(Near(NavigationCompassMath.Wrap(-180),180)&&Near(NavigationCompassMath.Wrap(180),180),"Both rear directions share one deterministic seam convention");Check(Near(NavigationCompassMath.ArcHeight(-1),NavigationCompassMath.ArcHeight(1))&&Near(NavigationCompassMath.ArcHeight(0),0),"Compass arc is symmetric and lowest at the center");
  double previous=1;for(int degree=0;degree<=90;degree++){var p=NavigationCompassMath.Project(0,1,0,degree);Check(p.scale<=previous+1e-12&&p.scale>=.36&&p.scale<=1,"Pitch scale is bounded and monotonic at "+degree+" degrees");previous=p.scale;}
  Check(Near(NavigationCompassMath.Project(0,0,1,-90).scale,.36),"Opposite pitch is minimized rather than falsely enlarged");
  bool nadirStable=true;for(int i=0;i<100;i++){double a=i*Math.PI/50;var p=NavigationCompassMath.Project(Math.Sin(a)*1e-7,Math.Cos(a)*1e-7,-1,-42);nadirStable&=Near(p.bearing,0)&&p.valid;}Check(nadirStable,"Float tangent residuals do not spin the planet directly below the observer");
  Check(Near(NavigationCompassMath.StableBearing(-179.99,179.99),179.99)&&Near(NavigationCompassMath.StableBearing(179.99,-179.99),-179.99),"Subpixel rear-seam noise cannot switch icons between opposite bar edges");Check(Near(NavigationCompassMath.StableBearing(-179,179.99),-179),"A target genuinely passing the rear seam still wraps to the other side");
  Directory.CreateDirectory("TestResults/Planetary/NavigationCompass");File.WriteAllText("TestResults/Planetary/NavigationCompass/math-summary.json","{\"status\":\"PASS\",\"checks\":"+count+"}");Console.WriteLine(count+" compass checks passed");
 }
}
